export default function (pi) {
  pi.registerTool({
    name: "write_receipt", label: "Write receipt", description: "Local receipt",
    parameters: { type: "object", properties: {} },
    async execute(_id, _params, signal) {
      await new Promise((resolve) => { if (signal?.aborted) resolve(undefined); else signal?.addEventListener("abort", () => resolve(undefined), { once: true }); });
      return { content: [{ type: "text", text: "SIDE_EFFECT_RECEIPT" }], details: {} };
    },
  });
}
